import { mkdir, readFile, readdir, rename, rm, stat } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import type { Context } from '@ruobai/cordis'
import { HttpError, readJson, sendJson } from '@ruobai/web-server'
import type {} from '@ruobai/session'

export interface Config {
  draftsRoot?: string
  skillsRoot?: string
}

export const name = 'skill-distiller-web'
export const inject = ['web', 'sessions']

/** Slugs are generated by the distiller; only its own alphabet is accepted. */
const SLUG = /^[a-z0-9\u4e00-\u9fa5][a-z0-9\u4e00-\u9fa5._-]*$/

/**
 * Draft review API.
 *
 * Approving a draft moves it from `.ruobai/skills-drafts/` into
 * `.ruobai/skills/`, which is a skill root; discarding deletes it. Nothing here
 * writes a skill body directly — the only way a draft becomes a skill is this
 * explicit, human-triggered move.
 */
export function apply(ctx: Context, config: Config = {}) {
  const draftsRoot = resolve(config.draftsRoot ?? '.ruobai/skills-drafts')
  const skillsRoot = resolve(config.skillsRoot ?? '.ruobai/skills')

  ctx.effect(() => ctx.web.register({
    prefix: '/api/skill-drafts',
    handler: async (req, res, url) => {
      if (url.pathname === '/api/skill-drafts' && (req.method ?? 'GET') === 'GET') {
        sendJson(res, 200, { drafts: await list(draftsRoot) })
        return true
      }
      if (req.method === 'POST') {
        const body = await readJson(req) as { slug?: unknown }
        const slug = typeof body?.slug === 'string' ? body.slug.trim() : ''
        if (!SLUG.test(slug)) throw new HttpError(400, 'invalid slug')

        if (url.pathname === '/api/skill-drafts/approve') {
          await approve(draftsRoot, skillsRoot, slug)
          sendJson(res, 200, { ok: true, slug })
          return true
        }
        if (url.pathname === '/api/skill-drafts/discard') {
          await rm(join(draftsRoot, slug), { recursive: true, force: true })
          sendJson(res, 200, { ok: true, slug })
          return true
        }
      }
      throw new HttpError(404, 'not found')
    },
  }), 'skill-distiller-web.api')
}

export default { name, inject, apply }

export interface DraftSummary {
  slug: string
  name: string
  description: string
  bytes: number
  updatedAt: number
}

export async function list(draftsRoot: string): Promise<DraftSummary[]> {
  let entries: string[]
  try {
    entries = await readdir(draftsRoot)
  } catch {
    return []
  }

  const drafts: DraftSummary[] = []
  for (const slug of entries) {
    if (!SLUG.test(slug)) continue
    const file = join(draftsRoot, slug, 'SKILL.md')
    try {
      const info = await stat(file)
      const body = await readFile(file, 'utf8')
      drafts.push({
        slug,
        name: frontmatter(body, 'name') || slug,
        description: frontmatter(body, 'description'),
        bytes: info.size,
        updatedAt: info.mtimeMs,
      })
    } catch {
      // A draft directory without SKILL.md is not a draft.
    }
  }
  return drafts.sort((left, right) => right.updatedAt - left.updatedAt)
}

export async function approve(draftsRoot: string, skillsRoot: string, slug: string) {
  const source = join(draftsRoot, slug)
  const target = join(skillsRoot, slug)
  try {
    await stat(source)
  } catch {
    throw new HttpError(404, `unknown draft: ${slug}`)
  }
  try {
    await stat(target)
    throw new HttpError(409, `a skill named ${slug} already exists`)
  } catch (error) {
    if (error instanceof HttpError) throw error
  }
  await mkdir(skillsRoot, { recursive: true })
  await rename(source, target)
  return target
}

function frontmatter(body: string, key: string): string {
  const match = new RegExp(`^${key}:\\s*(.+)$`, 'm').exec(body)
  return match?.[1]?.trim() ?? ''
}
